namespace kok {
 internal sealed class WorkspaceEdit {public string oldText="",newText="";}
 internal sealed class WorkspacePatch {public string path,full,before,after,beforeHash,afterHash;public byte[] bytes;}
 internal static class AgentWorkspaceTools {
  internal static readonly string[] Names={"workspace_info","search_workspace","read_workspace_file","git_workspace","apply_workspace_patch"};
  static readonly UTF8Encoding Utf8=new UTF8Encoding(false,true);
  const int MaxBytes=4*1024*1024;
  internal static bool Coding(string text){return Regex.IsMatch(text??"",@"代码|工作区|仓库|TypeScript|JavaScript|Python|C#|\b(?:coding|code|repository|workspace|bug)\b|\.(?:ts|js|py|cs)\b",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant);}
  internal static bool NeedsLibrary(string text){return Regex.IsMatch(text??"",@"资料库|所选资料|所选文档|根据[^。\n]{0,50}(?:资料|报告|文档)|library sources|selected documents",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant);}
  static readonly HashSet<string> Excluded=new HashSet<string>(new[]{".git",".svn",".hg","node_modules","dist","build","bin","obj",".venv","venv","__pycache__",".next",".cache"},StringComparer.OrdinalIgnoreCase);
  internal static bool Sensitive(string path){return (path??"").Replace('\\','/').Split('/').Any(part=>Regex.IsMatch(part,@"^(?:\.env(?:\..*)?|\.git|\.aws|\.ssh|\.azure|\.codex|\.npmrc|\.pypirc|credentials(?:\..*)?|secrets?(?:\..*)?|id_rsa|id_ed25519)$|\.(?:pem|pfx|p12|key|kokvault|sealed)$",RegexOptions.IgnoreCase|RegexOptions.CultureInvariant));}
  internal static void SafePath(string path,bool empty=false){AgentExecution.ValidateRelative(path,empty);if(Sensitive(path))throw new InvalidDataException("工作区凭据和私密配置不提供给 Agent。");}
  internal static string Redact(string text){return Regex.Replace(text??"",@"(?<![A-Za-z0-9])(?:sk-(?:proj-|or-v1-)?[A-Za-z0-9_-]{12,}|gh[pousr]_[A-Za-z0-9]{20,}|github_pat_[A-Za-z0-9_]{20,})","[redacted]");}
  internal static string Hash(byte[] bytes){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  internal static string RootId(Library library){return Hash(Utf8.GetBytes(Path.GetFullPath(AgentExecution.Root(library)).TrimEnd('\\','/').ToUpperInvariant()));}
  internal static byte[] Bytes(Library library,string path){SafePath(path);string full=AgentExecution.Resolve(library,path,false);var info=new FileInfo(full);if(!info.Exists)throw new FileNotFoundException("工作区文件不存在。",path);if(info.Length>MaxBytes)throw new InvalidDataException("工作区文本读取最多支持 4 MB 文件。");return File.ReadAllBytes(full);}
  static string Decode(byte[] bytes){if(bytes.Take(Math.Min(4096,bytes.Length)).Any(b=>b==0))throw new InvalidDataException("工作区工具只处理 UTF-8 文本。");int skip=bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191?3:0;try{return Utf8.GetString(bytes,skip,bytes.Length-skip);}catch(DecoderFallbackException){throw new InvalidDataException("工作区工具只处理 UTF-8 文本。");}}
  internal static List<Dictionary<string,object>> Inputs(Library library,Dictionary<string,object> args){var paths=AgentTaskState.Get<List<string>>(args,"inputs")??new List<string>();if(paths.Count>16)throw new InvalidDataException("inputs allows at most 16 files");string rootId=RootId(library);return paths.Distinct(StringComparer.OrdinalIgnoreCase).Select(p=>new Dictionary<string,object>{{"path",p},{"sha256",Hash(Bytes(library,p))},{"workspaceId",rootId}}).ToList();}
  internal static bool InputsCurrent(Library library,IEnumerable<Dictionary<string,object>> rows){try{return rows.All(r=>ModuleContext.Text(r,"workspaceId")==RootId(library)&&Hash(Bytes(library,ModuleContext.Text(r,"path")))==ModuleContext.Text(r,"sha256"));}catch{return false;}}
  internal static Dictionary<string,object> Read(Library library,Dictionary<string,object> args){
   string path=ModuleContext.Text(args,"path");byte[] bytes=Bytes(library,path);string text=Decode(bytes);string[] lines=text.Replace("\r\n","\n").Replace('\r','\n').Split('\n');int start=args.ContainsKey("startLine")?Convert.ToInt32(args["startLine"]):1,count=args.ContainsKey("lineCount")?Convert.ToInt32(args["lineCount"]):160;
   if(start<1||count<1||count>400)throw new InvalidDataException("startLine must be positive; lineCount must be 1-400");var shown=new List<string>();int used=0,index=start-1;
   for(;index<lines.Length&&shown.Count<count;index++){string line=lines[index];if(line.Length>16000)throw new InvalidDataException("单行内容过长，请缩小文件或使用专用工具。");if(used+line.Length>20000)break;shown.Add((index+1)+": "+Redact(line));used+=line.Length;}
   return new Dictionary<string,object>{{"text","Workspace "+path+"\n"+String.Join("\n",shown)},{"path",path},{"workspaceId",RootId(library)},{"sha256",Hash(bytes)},{"startLine",start},{"totalLines",lines.Length},{"hasMore",index<lines.Length},{"nextLine",index+1},{"assets",new[]{AgentExecution.WorkspaceAsset(library,path,"source")}}};
  }
  internal static WorkspacePatch Plan(Library library,Dictionary<string,object> args){
   string path=ModuleContext.Text(args,"path"),expected=ModuleContext.Text(args,"expectedHash");SafePath(path);string full=AgentExecution.Resolve(library,path,false);bool exists=File.Exists(full);byte[] before=exists?Bytes(library,path):new byte[0];string hash=exists?Hash(before):"missing";
   if(hash!=expected)throw new InvalidDataException("工作区文件已变化，请重新读取后再生成补丁。");
   var edits=AgentTaskState.Get<List<WorkspaceEdit>>(args,"edits")??new List<WorkspaceEdit>();if(edits.Count<1||edits.Count>16)throw new InvalidDataException("edits must contain 1-16 replacements");string original=Decode(before),after=original,newline=original.Contains("\r\n")?"\r\n":"\n";
   foreach(var edit in edits){if(edit.oldText==null||edit.newText==null)throw new InvalidDataException("Patch text is required");if(!exists){if(edits.Count!=1||edit.oldText.Length!=0)throw new InvalidDataException("New files require one empty oldText");after=edit.newText;break;}string old=edit.oldText.Replace("\r\n","\n").Replace("\n",newline),next=edit.newText.Replace("\r\n","\n").Replace("\n",newline);int at=after.IndexOf(old,StringComparison.Ordinal);if(old.Length==0||at<0||after.LastIndexOf(old,StringComparison.Ordinal)!=at)throw new InvalidDataException("补丁原文必须在当前文件中唯一匹配。");after=after.Substring(0,at)+next+after.Substring(at+old.Length);}
   if(after.Length>AgentExecution.MaxWriteChars||after==original)throw new InvalidDataException("补丁不能为空，且结果不能超过 200000 字符。");byte[] output=Utf8.GetBytes(after);if(before.Length>=3&&before[0]==239&&before[1]==187&&before[2]==191)output=new byte[]{239,187,191}.Concat(output).ToArray();
   return new WorkspacePatch{path=path,full=full,before=original,after=after,beforeHash=hash,afterHash=Hash(output),bytes=output};
  }
  internal static void Prepare(Library library,AgentCall call){WorkspacePatch plan;try{if(call.args.ContainsKey("workspaceId")&&ModuleContext.Text(call.args,"workspaceId")!=RootId(library))throw new InvalidDataException("工作区已变化，请重新审核补丁。");plan=Plan(library,call.args);}catch(InvalidDataException error){throw new FormatException(error.Message);}call.beforeText=Redact(plan.before);call.afterText=Redact(plan.after);call.args["resultHash"]=plan.afterHash;call.args["workspaceId"]=RootId(library);}
  internal static AgentToolReceipt Apply(ModuleContext context,AgentTaskState task,AgentCall call,CancellationToken token){
   context.Policy.Ensure(Need.NormalLibrary,"agent");token.ThrowIfCancellationRequested();if(ModuleContext.Text(call.args,"workspaceId")!=RootId(context.Library))throw new InvalidDataException("工作区已变化，请重新审核补丁。");string path=ModuleContext.Text(call.args,"path"),intended=ModuleContext.Text(call.args,"resultHash");SafePath(path);string full=AgentExecution.Resolve(context.Library,path,false);bool reused=File.Exists(full)&&intended.Length==64&&Hash(Bytes(context.Library,path))==intended;
   WorkspacePatch plan=null;if(!reused){plan=Plan(context.Library,call.args);if(intended.Length>0&&plan.afterHash!=intended)throw new InvalidDataException("补丁预览与执行结果不一致，请重新审核。");Directory.CreateDirectory(Path.GetDirectoryName(full));string temp=Path.Combine(Path.GetDirectoryName(full),".kok-"+Guid.NewGuid().ToString("N")+".tmp");try{File.WriteAllBytes(temp,plan.bytes);token.ThrowIfCancellationRequested();string current=File.Exists(full)?Hash(Bytes(context.Library,path)):"missing";if(current!=plan.beforeHash)throw new InvalidDataException("工作区文件已变化，请重新读取后再生成补丁。");if(current=="missing")File.Move(temp,full);else File.Replace(temp,full,null);}finally{if(File.Exists(temp))File.Delete(temp);}}
   string finalHash=Hash(Bytes(context.Library,path));return new AgentToolReceipt{result=new Dictionary<string,object>{{"text",(reused?"Already matches the approved patch: ":"Applied and read back workspace patch: ")+path},{"path",path},{"workspaceId",RootId(context.Library)},{"beforeHash",ModuleContext.Text(call.args,"expectedHash")},{"sha256",finalHash},{"reused",reused},{"readBackVerified",true},{"assets",new[]{AgentExecution.WorkspaceAsset(context.Library,path,"artifact")}}}};
  }
  internal static Dictionary<string,object> Search(Library library,Dictionary<string,object> args,CancellationToken token){
   string relative=ModuleContext.Text(args,"path"),query=ModuleContext.Text(args,"query"),glob=ModuleContext.Text(args,"glob");SafePath(relative,true);if(query.Length<1||query.Length>300)throw new InvalidDataException("query must be 1-300 characters");if(glob.Length==0)glob="*";if(glob.Length>100||glob.IndexOfAny(new[]{'/','\\',':'})>=0)throw new InvalidDataException("glob must be a filename pattern");string pattern="^"+Regex.Escape(glob).Replace("\\*",".*").Replace("\\?",".")+"$",root=AgentExecution.Resolve(library,relative,true);var stack=new Stack<string>();stack.Push(root);var rows=new List<object>();int visited=0,scanned=0,totalBytes=0;bool truncated=false;
   while(stack.Count>0){token.ThrowIfCancellationRequested();string dir=stack.Pop();foreach(string child in Directory.EnumerateFileSystemEntries(dir)){token.ThrowIfCancellationRequested();if(++visited>5000){truncated=true;stack.Clear();break;}string rel=child.Substring(Path.GetFullPath(AgentExecution.Root(library)).TrimEnd('\\').Length+1).Replace('\\','/');var attr=File.GetAttributes(child);if((attr&FileAttributes.ReparsePoint)!=0||Sensitive(rel))continue;if((attr&FileAttributes.Directory)!=0){if(!Excluded.Contains(Path.GetFileName(child)))stack.Push(child);continue;}if(!Regex.IsMatch(Path.GetFileName(child),pattern,RegexOptions.IgnoreCase))continue;var info=new FileInfo(child);if(info.Length>262144)continue;if(++scanned>1000||totalBytes+info.Length>8*1024*1024){truncated=true;stack.Clear();break;}totalBytes+=(int)info.Length;string text;try{text=Decode(File.ReadAllBytes(child));}catch(InvalidDataException){continue;}string[] lines=text.Replace("\r\n","\n").Split('\n');for(int line=0;line<lines.Length;line++)if(lines[line].IndexOf(query,StringComparison.OrdinalIgnoreCase)>=0){rows.Add(new{path=rel,line=line+1,text=Redact(lines[line].Substring(0,Math.Min(300,lines[line].Length)))});if(rows.Count>=100){truncated=true;stack.Clear();break;}}if(truncated)break;}}
   return new Dictionary<string,object>{{"text",Library.Json.Serialize(rows)},{"matches",rows},{"scannedFiles",scanned},{"truncated",truncated}};
  }
  internal static Dictionary<string,object> Git(Library library,Dictionary<string,object> args,CancellationToken token){
   string mode=ModuleContext.Text(args,"mode"),path=ModuleContext.Text(args,"path");SafePath(path,true);if(mode!="status"&&mode!="diff")throw new InvalidDataException("mode must be status or diff");string root=AgentExecution.Resolve(library,"",true);var argv=new List<string>{"--no-pager","-c","core.fsmonitor=false","-c","core.hooksPath=","--no-optional-locks"};argv.AddRange(mode=="status"?new[]{"status","--porcelain=v1","--untracked-files=normal"}:new[]{"diff","--no-ext-diff","--no-textconv","--no-color"});argv.Add("--");argv.Add(path.Length>0?path:".");foreach(string excluded in new[]{".env",".env.*","**/.env","**/.env.*","**/*.pem","**/*.key","**/credentials*","**/secrets*"})argv.Add(":(exclude)"+excluded);
   var start=new ProcessStartInfo{StandardOutputEncoding=new UTF8Encoding(false),StandardErrorEncoding=new UTF8Encoding(false),FileName="git.exe",WorkingDirectory=root,UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true,Arguments=String.Join(" ",argv.Select(AgentExecution.QuoteArgument))};start.EnvironmentVariables["GIT_OPTIONAL_LOCKS"]="0";string stdout,stderr;int exit;AgentExecution.RunProcess(start,15,token,out stdout,out stderr,out exit);return new Dictionary<string,object>{{"text",Redact(stdout+(stderr.Length>0?"\n"+stderr:""))},{"exitCode",exit},{"truncated",stdout.Length>=AgentExecution.MaxOutputChars}};
  }
internal static Dictionary<string,object> Info(Library library){string root=AgentExecution.Resolve(library,"",true);var markers=new[]{"AGENTS.md","package.json","tsconfig.json","pyproject.toml","requirements.txt","Cargo.toml","go.mod"}.Where(p=>File.Exists(Path.Combine(root,p))).Concat(Directory.EnumerateFiles(root,"*.csproj").Select(Path.GetFileName)).Concat(Directory.EnumerateFiles(root,"*.sln").Select(Path.GetFileName)).Take(30).ToArray();string bundledNode=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"runtime","research","node.exe");var tools=new[]{"git.exe","node.exe","python.exe","dotnet.exe"}.Select(n=>new{name=n,found=AgentExecution.ResolveExecutable(n)!=null,command=AgentExecution.ResolveExecutable(n)??""}).ToArray();string workspaceId=RootId(library);return new Dictionary<string,object>{{"text",Library.Json.Serialize(new{workspaceId,workspace=Path.GetFileName(root.TrimEnd('\\')),markers,tools,git=Directory.Exists(Path.Combine(root,".git"))||File.Exists(Path.Combine(root,".git")),bundledNode=File.Exists(bundledNode)?bundledNode:"",note="Executable discovery only; versions and tests have not been executed."})},{"workspaceId",workspaceId},{"markers",markers},{"tools",tools}};}
  static AgentToolSpec ReadTool(string name,string title,string description,Dictionary<string,object> properties,string[] required,Func<Library,AgentTaskState,AgentCall,CancellationToken,Task<Dictionary<string,object>>> run){return new AgentToolSpec{Name=name,Title=title,Description=description,Requires=Need.NormalLibrary,CapabilityId="agent."+name,Write=false,Signature=name,Properties=properties,Required=required,Read=run,Validate=(a,e)=>{if(a.args.ContainsKey("path"))SafePath(ModuleContext.Text(a.args,"path"),name!="read_workspace_file");}};}
  internal static AgentToolSpec[] Tools(){return new[]{
   ReadTool(Names[0],"识别代码工作区","Inspect project markers and installed executable availability in the configured workspace. Does not run project code or read credential/config secrets.",AgentRules.Props(),new string[0],(l,s,c,t)=>Task.Run(()=>Info(l),t)),
   ReadTool(Names[1],"搜索工作区代码","Bounded literal case-insensitive code search. Skips credentials, symlinks, dependencies and generated folders. Results include exact paths and line numbers; truncated is explicit.",AgentRules.Props("query",AgentRules.Str("Literal text",300),"path",AgentRules.Str("Relative folder",500),"glob",AgentRules.Str("Filename glob, e.g. *.ts",100)),new[]{"query"},(l,s,c,t)=>Task.Run(()=>Search(l,c.args,t),t)),
   ReadTool(Names[2],"分段读取代码","Read UTF-8 workspace text with line numbers and raw-byte SHA-256. Default 160 lines; follow nextLine when hasMore. Supply sha256 as expectedHash when proposing a patch. Secret files are excluded.",AgentRules.Props("path",AgentRules.Str("Relative file",500),"startLine",new Dictionary<string,object>{{"type","integer"},{"minimum",1}},"lineCount",new Dictionary<string,object>{{"type","integer"},{"minimum",1},{"maximum",400}}),new[]{"path"},(l,s,c,t)=>Task.Run(()=>Read(l,c.args),t)),
   ReadTool(Names[3],"读取 Git 状态与差异","Read workspace Git status or unstaged diff with external diff, textconv, fsmonitor, optional locks and pager disabled. No commits, resets or network. Secrets are excluded; preserve existing user changes.",AgentRules.Props("mode",AgentRules.Str("Read mode",10,new[]{"status","diff"}),"path",AgentRules.Str("Optional relative file/folder",500)),new[]{"mode"},(l,s,c,t)=>Task.Run(()=>Git(l,c.args,t),t)),
new AgentToolSpec{Name=Names[4],Title="应用工作区补丁",Write=true,Requires=Need.NormalLibrary,CapabilityId="agent."+Names[4],Signature="apply_workspace_patch{path,workspaceId,expectedHash,edits}",Description="PROPOSE exact local replacements in ONE UTF-8 file. First read its SHA-256 and workspaceId; for a new file obtain workspaceId from workspace_info; the host previews and rechecks it at approval, preserves unrelated text/BOM/newlines and atomically replaces the file. Each oldText must occur exactly once. To create a missing file use expectedHash=missing and one edit with empty oldText. Repeated approved calls that already match resultHash do not write again. Never patch credential files.",Properties=AgentRules.Props("path",AgentRules.Str("Relative file",500),"expectedHash",AgentRules.Str("Raw SHA-256 from read_workspace_file, or missing",64),"workspaceId",AgentRules.Str("workspaceId from workspace_info or read_workspace_file",64),"resultHash",AgentRules.Str("Host-supplied approved result hash; omit in proposals",64),"edits",AgentRules.Arr("Unique replacements",16,CapabilitySchema.Obj(AgentRules.Props("oldText",AgentRules.Str("Exact old text",200000),"newText",AgentRules.Str("Replacement",200000)),new[]{"oldText","newText"}))),Required=new[]{"path","workspaceId","expectedHash","edits"},Validate=(a,e)=>{SafePath(ModuleContext.Text(a.args,"path"));if(!Regex.IsMatch(ModuleContext.Text(a.args,"expectedHash"),"^(?:[a-f0-9]{64}|missing)$"))throw new FormatException("expectedHash must be a raw SHA-256 or missing");},ExecuteWithContext=(c,s,call,t)=>Task.FromResult(Apply(c,s,call,t))}
  };}
 }
